# owner: platform
import unittest

from hourglass.models import Span
from hourglass.gaps import find_gaps

NINE_TO_FIVE = Span(540, 1020)


class FindGapsTests(unittest.TestCase):
    def test_nothing_worked_is_one_gap(self):
        self.assertEqual(
            find_gaps([], NINE_TO_FIVE), ["gap 09:00-17:00 (480 min)"]
        )

    def test_gap_between_two_spans(self):
        worked = [Span(540, 720), Span(780, 1020)]
        self.assertEqual(find_gaps(worked, NINE_TO_FIVE), ["gap 12:00-13:00 (60 min)"])

    def test_gaps_at_both_ends(self):
        worked = [Span(600, 900)]
        self.assertEqual(
            find_gaps(worked, NINE_TO_FIVE),
            ["gap 09:00-10:00 (60 min)", "gap 15:00-17:00 (120 min)"],
        )

    def test_overlapping_spans_leave_no_gap(self):
        worked = [Span(540, 700), Span(650, 1020)]
        self.assertEqual(find_gaps(worked, NINE_TO_FIVE), [])

    def test_touching_spans_leave_no_gap(self):
        worked = [Span(540, 720), Span(720, 1020)]
        self.assertEqual(find_gaps(worked, NINE_TO_FIVE), [])

    def test_unordered_spans(self):
        worked = [Span(780, 1020), Span(540, 720)]
        self.assertEqual(find_gaps(worked, NINE_TO_FIVE), ["gap 12:00-13:00 (60 min)"])

    def test_span_starting_before_opening_raises(self):
        with self.assertRaises(ValueError):
            find_gaps([Span(500, 600)], NINE_TO_FIVE)

    def test_span_ending_after_opening_raises(self):
        with self.assertRaises(ValueError):
            find_gaps([Span(900, 1100)], NINE_TO_FIVE)
